struct Node {
    float g_value = 0.0f;
    float h_value = 0.0f;
};

Node* find_next_node(std::vector<Node*>& open_list) {
    if (open_list.empty()) return nullptr;

    size_t best_idx = 0;
    float min_f = open_list[0]->g_value + open_list[0]->h_value;

    for (size_t i = 1; i < open_list.size(); ++i) {
        float f = open_list[i]->g_value + open_list[i]->h_value;
        if (f < min_f) {
            min_f = f;
            best_idx = i;
        }
    }

    Node* best_node = open_list[best_idx];
    open_list[best_idx] = open_list.back();
    open_list.pop_back();
    return best_node;
}

int main() {
    Node n1{1.0f, 1.0f}; // f=2
    Node n2{0.5f, 0.5f}; // f=1
    Node n3{2.0f, 2.0f}; // f=4
    std::vector<Node*> open = {&n1, &n2, &n3};
    Node* result = find_next_node(open);
    if (result == &n2 && open.size() == 2) return 0;
    return 1;
}

